INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Definiert ein /48-Präfix immer genau 48 Bits für das Netzwerk?', 2, '[{"text": "Ja", "correct": true, "because": "Gibt Netzwerkanteil an"}, {"text": "Nein", "correct": false, "because": "Standard ist fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits bleiben bei einem /56-Präfix für die Interface-ID?', 3, '[{"text": "72", "correct": true, "because": "128 minus 56"}, {"text": "64", "correct": false, "because": "Für /64 typisch"}, {"text": "48", "correct": false, "because": "Für /80 typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Teil einer Adresse beschreibt ein /128-Präfix?', 4, '[{"text": "Komplette Adresse", "correct": true, "because": "Keine Interface-ID"}, {"text": "Netzwerkanteil", "correct": false, "because": "Zu groß für Teilung"}, {"text": "Hostanteil", "correct": false, "because": "Keine Teilung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /64 ist Standard für LAN. b) /48 ist für größere Organisationen üblich.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Standards der Praxis"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem /80-Präfix?', 5, '[{"text": "Übertragungsrate", "correct": true, "because": "Irrelevant für Präfix"}, {"text": "Netzwerkgrenze", "correct": false, "because": "Kern des Präfix"}, {"text": "Interface-ID", "correct": false, "because": "Rest der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /128-Präfix für Subnetze genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Nur eine Adresse"}, {"text": "Ja", "correct": false, "because": "Keine Teilung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein kleines Subnetz mit wenigen Geräten?', 3, '[{"text": "/126", "correct": true, "because": "2 Bits für 4 Adressen"}, {"text": "/64", "correct": false, "because": "Zu groß"}, {"text": "/48", "correct": false, "because": "Für Organisationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein /48-Präfix?', 5, '[{"text": "48 Bits Netzwerk", "correct": true, "because": "Definiert Subnetz"}, {"text": "80 Bits Interface-ID", "correct": true, "because": "128 - 48 = 80"}, {"text": "64 Bits Netzwerk", "correct": false, "because": "Falsche Teilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /64 ist für SLAAC nötig. b) /128 erlaubt mehrere Hosts. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur eine Adresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Präfix-Definition?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Kern der Definition"}, {"text": "Netzwerkanteil", "correct": false, "because": "Hauptzweck"}, {"text": "Bandbreitenangabe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein /56-Präfix mehr Netzwerkbits als /48?', 2, '[{"text": "Ja", "correct": true, "because": "56 > 48"}, {"text": "Nein", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile definiert ein /80-Präfix?', 4, '[{"text": "80 Bits Netzwerk", "correct": true, "because": "Präfix definiert"}, {"text": "48 Bits Interface-ID", "correct": true, "because": "128 - 80 = 48"}, {"text": "64 Bits Interface-ID", "correct": false, "because": "Falsche Teilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein /48-Präfix nur für große Netze ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Flexibel nutzbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem /64-Präfix?', 3, '[{"text": "Subnetzgrenze", "correct": true, "because": "Definiert Netzwerk"}, {"text": "Hostanzahl", "correct": false, "because": "Ergibt sich"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /128 definiert eine Einzeladresse. b) /56 hat mehr Interface-Bits als /64.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) keine Teilung, b) 72 > 64"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein /48-Präfix?', 5, '[{"text": "Viele Subnetze", "correct": true, "because": "16 Bits für Subnetze"}, {"text": "Organisationstauglich", "correct": true, "because": "Große Netzwerke"}, {"text": "SLAAC-Pflicht", "correct": false, "because": "Nur bei /64"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem /128-Präfix unwichtig?', 3, '[{"text": "Netzwerkanteil", "correct": false, "because": "Ganze Adresse"}, {"text": "Interface-ID", "correct": true, "because": "Keine Teilung"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Präfix"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein /64-Präfix weniger Netzwerkbits als /48?', 2, '[{"text": "Nein", "correct": true, "because": "64 > 48"}, {"text": "Ja", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /80-Präfix für SLAAC geeignet ist?', 3, '[{"text": "Nein", "correct": true, "because": "SLAAC braucht /64"}, {"text": "Ja", "correct": false, "because": "Falsche Länge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für eine Punkt-zu-Punkt-Verbindung?', 4, '[{"text": "/127", "correct": true, "because": "2 Adressen möglich"}, {"text": "/64", "correct": false, "because": "Zu groß"}, {"text": "/48", "correct": false, "because": "Für Subnetze"}]');
